const body = $('Webhook').item.json.body || {};
return [{
  json: {
    code: Number(body.code || 0),
    projectId: body.projectId || null,
    projectName: body.projectName || '',
    creditsUsed: body.creditsUsed ?? null,
    videos: Array.isArray(body.videos) ? body.videos : []
  },
  pairedItem: { item: 0 }
}];

const webhook = $('normalize-payload').item.json;
const meta = $('fetch-video-meta').item?.json || {};

const MAX_PER_NICHO_DAY = 4;
const MAX_PER_DAY = 16;
const MAX_PER_CANAL_DIA = 2;
const MAX_HORIZON_DAYS = 180;
const STRICT_DAYS = 30;
const MIN_VIRAL_SCORE = 7;
const MAX_CLIPS_PER_PROJECT = 3;
const WIN_START_H = 8;
const WIN_END_H = 22;
const STEP_S = ((WIN_END_H - WIN_START_H) * 3600) / MAX_PER_DAY;

const nicho = String(meta.nicho || 'mindset').toLowerCase();
const canal = String(meta.canal_id || '');

function dayKey(y, m, d) { return y + '-' + String(m).padStart(2, '0') + '-' + String(d).padStart(2, '0'); }
function addDays(dk, n) {
  const parts = dk.split('-').map(Number);
  const t = new Date(Date.UTC(parts[0], parts[1] - 1, parts[2] + n));
  return dayKey(t.getUTCFullYear(), t.getUTCMonth() + 1, t.getUTCDate());
}
function spToEpoch(dk, secOfDay) {
  const parts = dk.split('-').map(Number);
  return Math.floor(Date.UTC(parts[0], parts[1] - 1, parts[2], 3, 0, 0) / 1000) + secOfDay;
}
function randInt(a, b) { return Math.floor(Math.random() * (b - a + 1)) + a; }

const occupied = new Map();
const dayTotal = new Map();
const nichoDay = new Map();

function occSet(dk, slot, nch, cnl) {
  if (!occupied.has(dk)) occupied.set(dk, new Map());
  occupied.get(dk).set(slot, { nicho: nch, canal: cnl });
  dayTotal.set(dk, (dayTotal.get(dk) || 0) + 1);
  const nk = dk + '|' + nch;
  if (!nichoDay.has(nk)) nichoDay.set(nk, { count: 0, canal: new Map() });
  const cell = nichoDay.get(nk);
  cell.count += 1;
  if (cnl) cell.canal.set(cnl, (cell.canal.get(cnl) || 0) + 1);
}

const rows = $('fetch-agenda-global').all().map(i => i.json).filter(r => r && r.ts_unix);
for (const r of rows) {
  const unix = Number(r.ts_unix);
  const t = new Date((unix - 3 * 3600) * 1000);
  const dk = dayKey(t.getUTCFullYear(), t.getUTCMonth() + 1, t.getUTCDate());
  const sec = t.getUTCHours() * 3600 + t.getUTCMinutes() * 60 + t.getUTCSeconds();
  let slot = Math.round((sec - WIN_START_H * 3600) / STEP_S);
  if (slot < 0) slot = 0;
  if (slot > MAX_PER_DAY - 1) slot = MAX_PER_DAY - 1;
  const dm = occupied.get(dk);
  if (dm) { while (dm.has(slot) && slot < MAX_PER_DAY - 1) slot++; }
  occSet(dk, slot, String(r.nicho || '').toLowerCase(), String(r.canal_id || ''));
}

function prevNicho(dk, slot, crossDay) {
  const dm = occupied.get(dk);
  if (dm) { for (let s = slot - 1; s >= 0; s--) if (dm.has(s)) return dm.get(s).nicho; }
  if (!crossDay) return null;
  let cur = dk;
  for (let i = 0; i < 60; i++) {
    cur = addDays(cur, -1);
    const m2 = occupied.get(cur);
    if (m2 && m2.size) {
      let best = -1;
      for (const s of m2.keys()) if (s > best) best = s;
      return m2.get(best).nicho;
    }
  }
  return null;
}
function nextNicho(dk, slot, crossDay) {
  const dm = occupied.get(dk);
  if (dm) { for (let s = slot + 1; s < MAX_PER_DAY; s++) if (dm.has(s)) return dm.get(s).nicho; }
  if (!crossDay) return null;
  let cur = dk;
  for (let i = 0; i < 60; i++) {
    cur = addDays(cur, 1);
    const m2 = occupied.get(cur);
    if (m2 && m2.size) {
      let best = MAX_PER_DAY;
      for (const s of m2.keys()) if (s < best) best = s;
      return m2.get(best).nicho;
    }
  }
  return null;
}

function tryPlace(startDk, fromOff, toOff, crossDay) {
  for (let off = fromOff; off < toOff; off++) {
    const dk = addDays(startDk, off);
    if ((dayTotal.get(dk) || 0) >= MAX_PER_DAY) continue;
    const cell = nichoDay.get(dk + '|' + nicho) || { count: 0, canal: new Map() };
    if (cell.count >= MAX_PER_NICHO_DAY) continue;
    if ((cell.canal.get(canal) || 0) >= MAX_PER_CANAL_DIA) continue;
    const dm = occupied.get(dk) || new Map();
    for (let slot = 0; slot < MAX_PER_DAY; slot++) {
      if (dm.has(slot)) continue;
      if (prevNicho(dk, slot, crossDay) === nicho) continue;
      if (nextNicho(dk, slot, crossDay) === nicho) continue;
      return { dk, slot, off };
    }
  }
  return null;
}

function buildDescription(v) {
  const parts = [];
  if (v.viralReason) parts.push(String(v.viralReason).trim());
  if (v.transcript) {
    const trans = String(v.transcript).replace(/\n+/g, ' ').trim();
    if (trans) parts.push(trans.substring(0, 280));
  }
  let topics = [];
  try { topics = typeof v.relatedTopic === 'string' ? JSON.parse(v.relatedTopic) : (v.relatedTopic || []); } catch (e) { topics = []; }
  const hashtags = (Array.isArray(topics) ? topics : [])
    .map(t => String(t).toLowerCase().replace(/[^a-z0-9]/g, ''))
    .filter(t => t.length >= 3 && t.length <= 30)
    .slice(0, 8)
    .map(t => '#' + t);
  hashtags.push('#shorts');
  return { descricao: parts.join('\n\n').substring(0, 1500), hashtags: hashtags.join(' ') };
}
