function buildJson(v, publishTime, dk, pos, fb) {
  const desc = buildDescription(v);
  const titulo = String(v.title || meta.titulo_original || 'Clip').substring(0, 100);
  const descricaoFinal = desc.descricao + '\n\n' + desc.hashtags;
  const o = {
    video_origem_id: meta.video_origem_id || '',
    canal_id: canal,
    nicho: nicho,
    vizard_video_id: v.videoId ? Number(v.videoId) : 0,
    clip_url: sq(v.videoUrl || ''),
    transcript_raw: sq(String(v.transcript || '').substring(0, 5000)),
    titulo_final: sq(titulo),
    descricao_base: sq(desc.descricao),
    descricao_final: sq(descricaoFinal),
    hashtags_str: sq(desc.hashtags),
    score_clip: Number(v._score || 0),
    duracao: Math.round((v.videoMsDuration || 0) / 1000),
    publish_time: publishTime,
    publish_time_iso: new Date(publishTime * 1000).toISOString(),
    _debug_day: dk,
    _debug_pos: pos
  };
  if (fb) o._fallback = true;
  return { json: o, pairedItem: { item: 0 } };
}

const rawVideos = Array.isArray(webhook.videos) ? webhook.videos : [];
if (rawVideos.length === 0) {
  return [{ json: { _no_clips: true }, pairedItem: { item: 0 } }];
}
function normScore(s) { let n = Number(s) || 0; if (n > 10) n = n / 10; return n; }
const vids = rawVideos.map(v => ({ ...v, _score: normScore(v.viralScore) })).sort((a, b) => b._score - a._score);
let selected = vids.filter(v => v._score >= MIN_VIRAL_SCORE).slice(0, MAX_CLIPS_PER_PROJECT);
if (selected.length === 0) selected = [vids[0]];

const nowSp = new Date(Date.now() - 3 * 3600 * 1000);
const startDk = addDays(dayKey(nowSp.getUTCFullYear(), nowSp.getUTCMonth() + 1, nowSp.getUTCDate()), 1);

const result = [];
let searchOffset = 0;

for (let idx = 0; idx < selected.length; idx++) {
  const v = selected[idx];
  let hit = tryPlace(startDk, searchOffset, STRICT_DAYS, true);
  if (!hit) hit = tryPlace(startDk, searchOffset, MAX_HORIZON_DAYS, false);

  if (hit) {
    let secOfDay = WIN_START_H * 3600 + Math.floor(hit.slot * STEP_S) + randInt(-90, 90);
    const minSec = WIN_START_H * 3600;
    const maxSec = WIN_END_H * 3600 - 1;
    if (secOfDay < minSec) secOfDay = minSec;
    if (secOfDay > maxSec) secOfDay = maxSec;
    const publishTime = spToEpoch(hit.dk, secOfDay);
    occSet(hit.dk, hit.slot, nicho, canal);
    searchOffset = hit.off;
    result.push(buildJson(v, publishTime, hit.dk, hit.slot, false));
  } else {
    const dk = addDays(startDk, MAX_HORIZON_DAYS);
    const slot = idx % MAX_PER_DAY;
    const publishTime = spToEpoch(dk, WIN_START_H * 3600 + Math.floor(slot * STEP_S));
    result.push(buildJson(v, publishTime, dk, slot, true));
  }
}

return result;

