  } else {
    const dk = addDays(startDk, MAX_HORIZON_DAYS);
    const slot = idx % MAX_PER_DAY;
    const publishTime = spToEpoch(dk, WIN_START_H * 3600 + Math.floor(slot * STEP_S));
    result.push(buildJson(v, publishTime, dk, slot, true));
  }
}

return result;

const clip = $('loop-by-clip').item.json;
const clipDb = $('insert-clip').item.json;
const res = $input.first().json || {};

function skipItem(motivo, platform, id, name) {
  return { json: {
    clip_db_id: clipDb.id,
    conta_ativa: false,
    skip_motivo: motivo,
    account_platform: platform || 'todas',
    account_id: id || '',
    account_name: name || '',
    publish_time: Number(clip.publish_time || 0)
  }, pairedItem: { item: 0 } };
}

if (res.error) {
  return [skipItem('falha ao listar contas Vizard: ' + String(res.error).substring(0, 200), 'todas', '', '')];
}

const raw = Array.isArray(res.accounts) ? res.accounts
          : Array.isArray(res.publishAccounts) ? res.publishAccounts
          : Array.isArray(res.data?.accounts) ? res.data.accounts
          : Array.isArray(res.data) ? res.data
          : [];

if (raw.length === 0) {
  return [skipItem('nenhuma conta conectada na Vizard', 'todas', '', '')];
}

const SUPPORTED = new Set(['tiktok', 'youtube', 'instagram', 'facebook', 'twitter', 'linkedin']);
function mapPlatform(p0) {
  const p = String(p0 || '').toLowerCase().trim();
  if (SUPPORTED.has(p)) return p;
  if (p.includes('tiktok') || p === 'tt') return 'tiktok';
  if (p.includes('youtube') || p === 'yt' || p.includes('shorts')) return 'youtube';
  if (p.includes('instagram') || p === 'ig' || p.includes('reels')) return 'instagram';
  if (p.includes('facebook') || p === 'fb') return 'facebook';
  if (p.includes('twitter') || p === 'x') return 'twitter';
  if (p.includes('linkedin') || p === 'li') return 'linkedin';
  return null;
}

const POST_LIMITS = { tiktok: 2200, instagram: 2200, facebook: 2200, youtube: 5000, twitter: 280, linkedin: 3000 };
const TITLE_LIMIT_YT = 100;
const out = [];

for (const account of raw) {
  const platform = mapPlatform(account.platform || account.type || account.socialPlatform);
  const accId = String(account.id || account.socialAccountId || account.socialId || '');
  const accName = account.username || account.page || account.name || '';
  const status = String(account.status || account.state || account.connectionStatus || '').toLowerCase().trim();

  if (!platform) continue;

  if (status !== 'active') {
    out.push(skipItem('conta nao ativa (status: ' + (status || 'desconhecido') + ')', platform, accId, accName));
    continue;
  }
  if (!Number(clip.vizard_video_id)) {
    out.push(skipItem('clip sem finalVideoId valido', platform, accId, accName));
    continue;
  }

  const limit = POST_LIMITS[platform] || 2200;
  out.push({ json: {
    clip_db_id: clipDb.id,
    conta_ativa: true,
    vizard_video_id: Number(clip.vizard_video_id || 0),
    titulo_final: platform === 'youtube' ? String(clip.titulo_final || '').substring(0, TITLE_LIMIT_YT) : '',
    post: String(clip.descricao_base || '').substring(0, limit),
    nicho: clip.nicho || '',
    publish_time: Number(clip.publish_time || 0),
    publish_time_iso: clip.publish_time_iso || new Date(Number(clip.publish_time || 0) * 1000).toISOString(),
    account_id: accId,
    account_platform: platform,
    account_name: accName
  }, pairedItem: { item: 0 } });
}

if (out.length === 0) {
  return [skipItem('nenhuma conta ativa/suportada na Vizard', 'todas', '', '')];
}

return out;

const payload = $('expand-by-account').item.json;
const res = $input.first().json || {};
const now = Math.floor(Date.now() / 1000);

let ok = false, code = null, err = null, pubId = null;

if (res.error) {
  const msg = String(res.error);
  const m = msg.match(/Vizard API error (-?\d+)/i);
  code = m ? Number(m[1]) : null;
  err = msg.substring(0, 500).replace(/'/g, '');
} else {
  code = Number(res.code);
  ok = code === 2000;
  if (ok) {
    pubId = (res.data && (res.data.id || res.data.videoId)) || null;
  } else {
    err = String(code + ': resposta inesperada da Vizard').replace(/'/g, '');
  }
}

const scheduled = ok && Number(payload.publish_time || 0) > now + 60;

return [{ json: {
  clip_db_id: payload.clip_db_id,
  account_platform: payload.account_platform,
  account_id: payload.account_id,
  account_name: payload.account_name,
  publish_time: payload.publish_time,
  vizard_code: code,
  pub_status: ok ? (scheduled ? 'agendado' : 'publicado') : 'erro',
  pub_platform_id: pubId,
  publish_error: err
}, pairedItem: { item: 0 } }];

return $input.all().map(i => {
  const p = i.json || {};
  return { json: {
    clip_db_id:       p.clip_db_id,
    account_platform: p.account_platform || 'todas',
    account_id:       p.account_id || '',
    account_name:     p.account_name || '',
    publish_time:     Number(p.publish_time || 0),
    vizard_code:      null,
    pub_status:       'erro',
    pub_platform_id:  null,
    publish_error:    String(p.skip_motivo || 'conta indisponivel').substring(0, 300).replace(/'/g, '')
  } };
});
